def _validate_braces(self):
    """Validate that all braces in the format string are properly matched.

    Every '{' must either be part of '{{' (escaped) or start a field pattern
    with a matching '}'. Similarly, every '}' must either be part of '}}' 
    (escaped) or close a field pattern opened by '{'.
    """
    i = 0
    fmt = self._format
    while i < len(fmt):
        if fmt[i] == '{':
            # Check for escaped {{
            if i + 1 < len(fmt) and fmt[i+1] == '{':
                i += 2
                continue
            # Find matching }
            depth = 1
            j = i + 1
            found_close = False
            while j < len(fmt):
                if fmt[j] == '{':
                    if j + 1 < len(fmt) and fmt[j+1] == '{':
                        j += 2
                        continue
                    depth += 1
                elif fmt[j] == '}':
                    if j + 1 < len(fmt) and fmt[j+1] == '}':
                        j += 2
                        continue
                    depth -= 1
                    if depth == 0:
                        found_close = True
                        break
                j += 1
            if not found_close:
                raise ValueError('pattern has unmatched opening brace(s)')
            i = j + 1
        elif fmt[i] == '}':
            # Check for escaped }}
            if i + 1 < len(fmt) and fmt[i+1] == '}':
                i += 2
                continue
            # Unmatched closing brace
            raise ValueError('pattern has unmatched closing brace(s)')
        else:
            i += 1

